"use client"

import type { ComponentProps, ReactNode } from "react"

import { cn } from "@/lib/utils"
import { BoardNavigationProvider, useBoardNavigation } from "@/components/ui/board-navigation"
import {
  ScrollArea,
  ScrollAreaContent,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaViewport,
} from "@/components/ui/scroll-area"
import {
  BoardColumn,
  BoardColumnGroup,
  boardColumnLabels,
  type BoardColumnLabels,
  type BoardColumnProps,
  type BoardColumnGroupProps,
} from "@/components/ui/board-column"
import {
  BoardItem,
  BoardItemHandle,
  BoardList,
  BoardTransfer,
  useBoardLists,
  type BoardItemHandleProps,
  type BoardItemProps,
} from "@/components/ui/board-transfer"
import type { BoardTransferOptions } from "@/components/ui/board-transfer-primitive"

export { BoardItem, BoardItemHandle, BoardColumn, BoardColumnGroup, BoardList, boardColumnLabels, useBoardLists }
export type { BoardItemHandleProps, BoardItemProps, BoardColumnLabels, BoardColumnProps, BoardColumnGroupProps }

type BoardName =
  | { "aria-label": string; "aria-labelledby"?: never }
  | { "aria-labelledby": string; "aria-label"?: never }

type BoardProps = Omit<
  ComponentProps<typeof ScrollArea>,
  "aria-label" | "aria-labelledby" | "children" | "defaultValue"
> &
  BoardName &
  BoardTransferOptions & { children?: ReactNode }

const transferKeys = [
  "value",
  "defaultValue",
  "onValueChange",
  "order",
  "accepts",
  "disabledKeys",
  "handle",
  "handleFocus",
  "autoScroll",
  "itemLabel",
  "listLabel",
  "labels",
  "agentMoves",
] as const satisfies readonly (keyof BoardTransferOptions)[]

function splitTransfer<Props extends BoardTransferOptions>(props: Props) {
  const transfer: BoardTransferOptions = {}
  const rest: Record<string, unknown> = { ...props }
  for (const key of transferKeys) {
    if (key in rest) {
      Object.assign(transfer, { [key]: rest[key] })
      delete rest[key]
    }
  }
  return { transfer, rest: rest as Omit<Props, (typeof transferKeys)[number]> }
}

/**
 * Columns of cards. With `value` (or `defaultValue`) and `onValueChange`, cards move between columns: each
 * `BoardColumn` with a `value` renders its list's cards with its `children` function, as `BoardItem`s.
 */
function Board({
  className,
  children,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...all
}: BoardProps) {
  const { transfer, rest: props } = splitTransfer(all)
  const navigation = useBoardNavigation()
  const board = (
    <ScrollArea
      type="auto"
      className={cn("w-full", transfer.value || transfer.defaultValue ? undefined : className)}
      {...props}
    >
      <ScrollAreaViewport render={<section />} aria-label={ariaLabel} aria-labelledby={ariaLabelledBy}>
        {/* oxlint-disable-next-line p-otero/spacing-tokens -- room for the h-2 horizontal scrollbar so it never covers the columns */}
        <ScrollAreaContent render={<ul />} className="flex w-max min-w-full items-start gap-section pb-2">
          <BoardNavigationProvider handle={navigation}>{children}</BoardNavigationProvider>
        </ScrollAreaContent>
      </ScrollAreaViewport>
      <ScrollAreaScrollbar orientation="horizontal">
        <ScrollAreaThumb />
      </ScrollAreaScrollbar>
    </ScrollArea>
  )
  if (!transfer.value && !transfer.defaultValue) return board
  return (
    <BoardTransfer
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      className={cn("w-full", className)}
      {...transfer}
    >
      {board}
    </BoardTransfer>
  )
}

export { Board }
export type { BoardProps }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import type { CollapsibleOpenChangeReason } from "@ui-sdk/react/collapsible"
import { CollapsiblePanel } from "@ui-sdk/react/collapsible"
import { Children, createContext, use, useId, useState, type ComponentProps, type ReactNode } from "react"
import { CircleMinusIcon, CirclePlusIcon } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { BoardList, useBoardLists } from "@/components/ui/board-transfer"
import { Collapsible, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Empty } from "@/components/ui/empty"
import {
  ScrollArea,
  ScrollAreaContent,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaViewport,
} from "@/components/ui/scroll-area"
import { ControlTooltip } from "@/components/ui/tooltip"
import type { Tone } from "@/lib/tone"
import { cn } from "@/lib/utils"

type HeadingLevel = 2 | 3 | 4 | 5 | 6

type BoardColumnLabels = {
  /** Accessible name of the collapse button; must contain the tooltip's words for voice control. */
  collapse: (title: string) => string
  expand: (title: string) => string
  collapseTooltip: string
  expandTooltip: string
}

const boardColumnLabels: BoardColumnLabels = {
  collapse: (title) => `Collapse ${title}`,
  expand: (title) => `Expand ${title}`,
  collapseTooltip: "Collapse column",
  expandTooltip: "Expand column",
}

const toneColor = {
  neutral: "[--column-tone:var(--input-strong)]",
  info: "[--column-tone:var(--info)]",
  success: "[--column-tone:var(--success)]",
  warning: "[--column-tone:var(--warning)]",
  destructive: "[--column-tone:var(--destructive)]",
  violet: "[--column-tone:var(--violet)]",
} satisfies Record<Tone, string>

function CollapseIcon({ collapsed }: { collapsed: boolean }) {
  const Icon = collapsed ? CirclePlusIcon : CircleMinusIcon
  return <Icon data-slot="board-column-collapse-icon" data-icon={collapsed ? "circle-plus" : "circle-minus"} />
}

const HeadingLevelContext = createContext<HeadingLevel>(3)

function Count({ value, className }: { value: ReactNode; className?: string }) {
  if (value === undefined || value === null || value === false) return null
  return (
    <Badge variant="secondary" data-slot="board-column-count" className={className}>
      {value}
    </Badge>
  )
}

type BoardColumnProps = Omit<ComponentProps<"li">, "title" | "children" | "value"> & {
  title: string
  /** The column's list in a board that moves cards; its `children` function renders the list's cards. */
  value?: string
  count?: number | ReactNode
  actions?: ReactNode
  empty?: ReactNode
  headingLevel?: HeadingLevel
  /** Marks the column with a dot before the title, a top border and a faint wash in this tone. */
  tone?: Tone
  collapsible?: boolean
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean, details: ChangeDetails<CollapsibleOpenChangeReason>) => void
  labels?: Partial<BoardColumnLabels>
  /** The cards, or, with `value` on a board that moves cards, a function from the column's card ids to them. */
  children?: ReactNode | ((ids: string[]) => ReactNode)
}

function BoardColumn({
  value,
  title,
  count,
  actions,
  empty,
  headingLevel = 3,
  tone,
  collapsed: collapsedProp,
  defaultCollapsed,
  onCollapsedChange,
  collapsible: collapsibleProp,
  labels,
  className,
  children,
  ...props
}: BoardColumnProps) {
  const collapsible =
    collapsibleProp ??
    (collapsedProp !== undefined || onCollapsedChange !== undefined || defaultCollapsed !== undefined)
  const titleId = useId()
  const [uncontrolled, setUncontrolled] = useState(defaultCollapsed ?? false)
  const collapsed = collapsible && (collapsedProp ?? uncontrolled)
  const Heading = `h${headingLevel}` as const
  const groupHeadingLevel = Math.min(headingLevel + 1, 6) as HeadingLevel
  const { collapse, expand, collapseTooltip, expandTooltip } = { ...boardColumnLabels, ...labels }
  const lists = useBoardLists()
  const ids = value === undefined ? undefined : lists?.[value]
  const cards = typeof children === "function" ? children(ids ?? []) : children
  const shownCount = count === undefined && ids ? ids.length : count
  const isEmpty = ids ? ids.length === 0 : Children.toArray(cards).length === 0

  const header = (
    <div
      data-slot="board-column-header"
      className="group/board-column-header flex min-h-control-sm items-center gap-inline px-inset-item group-data-collapsed/board-column:flex-col group-data-collapsed/board-column:px-items"
    >
      {tone && (
        <span
          aria-hidden="true"
          data-slot="board-column-dot"
          className="size-2 shrink-0 rounded-full bg-(--column-tone)"
        />
      )}
      <Heading
        id={titleId}
        data-slot="board-column-title"
        className="min-w-0 flex-1 truncate text-sm font-semibold group-data-collapsed/board-column:text-vertical group-data-collapsed/board-column:overflow-visible"
      >
        {title}
      </Heading>
      <Count value={shownCount} />
      {actions !== undefined && (
        <div
          data-slot="board-column-actions"
          className="flex items-center gap-inline group-data-collapsed/board-column:hidden"
        >
          {actions}
        </div>
      )}
      {collapsible && (
        <ControlTooltip
          label={collapsed ? expand(title) : collapse(title)}
          tooltip={collapsed ? expandTooltip : collapseTooltip}
          agentPressable
        >
          <CollapsibleTrigger
            aria-label={collapsed ? expand(title) : collapse(title)}
            className="size-control-sm shrink-0 justify-center px-0 text-muted-foreground opacity-0 group-focus-within/board-column-header:opacity-100 group-hover/board-column-header:opacity-100 group-data-collapsed/board-column:order-first group-data-collapsed/board-column:opacity-100 focus-visible:opacity-100 pointer-coarse:opacity-100"
          >
            <CollapseIcon collapsed={collapsed} />
          </CollapsibleTrigger>
        </ControlTooltip>
      )}
    </div>
  )

  const body = (
    <ScrollArea className="flex min-h-0 flex-col">
      <ScrollAreaViewport aria-labelledby={titleId} className="h-auto max-h-(--board-column-max-height)">
        <ScrollAreaContent className="flex flex-col gap-items px-items pb-items content-auto">
          {isEmpty && empty !== undefined && <Empty className="p-group">{empty}</Empty>}
          {ids && value !== undefined ? (
            <BoardList value={value} aria-labelledby={titleId}>
              {cards}
            </BoardList>
          ) : (
            !isEmpty && cards
          )}
        </ScrollAreaContent>
      </ScrollAreaViewport>
      <ScrollAreaScrollbar>
        <ScrollAreaThumb />
      </ScrollAreaScrollbar>
    </ScrollArea>
  )

  const surface = cn(
    "flex w-full flex-col gap-inline rounded-surface border bg-muted/(--glass-opacity) pt-inline backdrop-surface group-data-collapsed/board-column:pb-items",
    tone && "board-column-wash border-t-2 border-t-(--column-tone)",
  )

  return (
    <li
      data-slot="board-column"
      data-collapsed={collapsed ? "" : undefined}
      data-tone={tone}
      className={cn(
        tone && toneColor[tone],
        "group/board-column flex max-w-(--board-column-max-width) min-w-(--board-column-min-width) flex-1 data-collapsed:max-w-none data-collapsed:min-w-0 data-collapsed:flex-none",
        className,
      )}
      {...props}
    >
      <HeadingLevelContext value={groupHeadingLevel}>
        {collapsible ? (
          <Collapsible
            render={<section aria-labelledby={titleId} />}
            className={surface}
            open={!collapsed}
            onOpenChange={(open, details) => {
              onCollapsedChange?.(!open, details)
              if (!details.canceled) setUncontrolled(!open)
            }}
          >
            {header}
            <CollapsiblePanel>{body}</CollapsiblePanel>
          </Collapsible>
        ) : (
          <section aria-labelledby={titleId} className={surface}>
            {header}
            {body}
          </section>
        )}
      </HeadingLevelContext>
    </li>
  )
}

type BoardColumnGroupProps = Omit<ComponentProps<"section">, "title"> & {
  title: string
  count?: number | ReactNode
}

function BoardColumnGroup({ title, count, className, children, ...props }: BoardColumnGroupProps) {
  const titleId = useId()
  const Heading = `h${use(HeadingLevelContext)}` as const
  return (
    <section
      aria-labelledby={titleId}
      data-slot="board-column-group"
      className={cn("flex flex-col gap-items", className)}
      {...props}
    >
      <div data-slot="board-column-group-header" className="flex items-center gap-inline px-inline pt-inline">
        <Heading id={titleId} className="min-w-0 flex-1 truncate text-xs font-medium text-muted-foreground">
          {title}
        </Heading>
        <Count value={count} />
      </div>
      {children}
    </section>
  )
}

export { BoardColumn, BoardColumnGroup, boardColumnLabels }
export type { BoardColumnGroupProps, BoardColumnLabels, BoardColumnProps }

import { createRovingFocus, definePrimitive, selects, type RovingFocusMoveContext } from "@ui-sdk/core"

type BoardNavigationOptions = {
  /** Enter on a card whose part isn't itself a link or button. */
  onOpen?: (id: string, event: KeyboardEvent) => void
}

type Card = RovingFocusMoveContext["items"][number]

const columnOf = (el: HTMLElement) => el.closest('[data-slot="board-column"]')

/** The cards in their columns, columns in document order, leaving out columns with no card that can take focus. */
function columnsOf(items: RovingFocusMoveContext["items"]) {
  const columns = new Map<Element | null, Card[]>()
  for (const item of items) {
    const column = columnOf(item.el)
    columns.set(column, [...(columns.get(column) ?? []), item])
  }
  return [...columns.values()]
}

function isActivator(el: HTMLElement) {
  return el instanceof HTMLAnchorElement || el instanceof HTMLButtonElement || el.getAttribute("role") === "button"
}

/** Where a key press goes on the board, as a column step, a row step or a jump; undefined for keys it leaves alone. */
function stepOf(event: KeyboardEvent, rtl: boolean) {
  if (event.altKey || event.shiftKey) return undefined
  const corner = event.ctrlKey || event.metaKey
  if (event.key === "Home") return corner ? ("board-first" as const) : ("first" as const)
  if (event.key === "End") return corner ? ("board-last" as const) : ("last" as const)
  if (corner) return undefined
  switch (event.key) {
    case "ArrowDown":
    case "j":
      return { row: 1 }
    case "ArrowUp":
    case "k":
      return { row: -1 }
    case "ArrowRight":
      return { column: rtl ? -1 : 1 }
    case "ArrowLeft":
      return { column: rtl ? 1 : -1 }
    default:
      return undefined
  }
}

function target(event: KeyboardEvent, { from, items, rtl }: RovingFocusMoveContext) {
  const step = stepOf(event, rtl)
  if (step === undefined) return undefined
  const columns = columnsOf(items)
  const column = columns.findIndex((cards) => cards.some((card) => card.key === from.key))
  const cards = columns[column]
  if (!cards) return undefined
  const row = cards.findIndex((card) => card.key === from.key)
  if (step === "first") return cards[0]
  if (step === "last") return cards.at(-1)
  if (step === "board-first") return items[0]
  if (step === "board-last") return items.at(-1)
  if (step.row !== undefined) return cards[row + step.row]
  // Across columns the card keeps its row, or takes the last one of a shorter column, as on a Linear board.
  const next = columns[column + step.column]
  return next?.[Math.min(row, next.length - 1)]
}

function move(event: KeyboardEvent, moveContext: RovingFocusMoveContext) {
  const card = target(event, moveContext)
  card?.el.scrollIntoView({ block: "nearest", inline: "nearest" })
  return card?.key
}

/**
 * One tab stop for a board's cards, on UI SDK's roving focus: ←/→ move between columns keeping the row (the
 * last card of a shorter column), ↑/↓ and j/k within a column, Home/End to a column's ends and Ctrl/⌘ with them
 * to the board's. Enter opens a card whose part isn't a link or button. A move changes two cards.
 */
const boardNavigation = definePrimitive({
  name: "board-navigation",
  options: { onOpen: "callback" },
  state: (_options: BoardNavigationOptions) => ({ active: null as string | null }),
  api: (context) => {
    const roving = createRovingFocus(context, { slot: "card", key: "active", move })
    return {
      roving,
      keydown(event: KeyboardEvent, el: HTMLElement, id: string) {
        if (event.defaultPrevented || event.target !== el) return
        if (roving.keydown(event, el)) {
          event.preventDefault()
          return
        }
        const { onOpen } = context.options()
        if (event.key === "Enter" && onOpen && !isActivator(el)) {
          event.preventDefault()
          onOpen(id, event)
        }
      },
      /** Gives a card the tab stop without moving focus, like when focus lands on one of its own controls. */
      activate: (id: string) => context.store.set({ active: id }),
      active: () => context.store.get().active,
    }
  },
  slots: (slot) => ({
    root: slot({}),
    card: slot<{ value: string }>({
      props: { value: "string" },
      // Only the card losing and the one taking `active` hear a move; before the board is entered every card may
      // claim the stop, so all hear `null`.
      selects: selects({ active: ({ key }) => [key, null] }),
      attrs: (state, part) => ({
        tabindex: part.api.roving.tabIndex(state, part),
        "data-active": state.active === part.key ? "" : undefined,
      }),
      on: {
        keydown: (event, { el, api, key }) => {
          if (el) api.keydown(event, el, key)
        },
      },
      bind: (el, part) => part.api.roving.bind(el, part),
    }),
  }),
  // Keys are a people-only accelerator: agents select and act on cards through the board's own parts and actions.
  agent: { actions: [], shown: () => false },
})

export { boardNavigation }
export type { BoardNavigationOptions }

"use client"

import { usePart, usePrimitive, type PrimitiveHandle } from "@ui-sdk/react/primitive"
import { createContext, use, useMemo, type ReactElement, type ReactNode } from "react"

import { boardNavigation, type BoardNavigationOptions } from "@/components/ui/board-navigation-primitive"

type BoardNavigationHandle = PrimitiveHandle<typeof boardNavigation>

const BoardNavigationContext = createContext<BoardNavigationHandle | null>(null)

/** The instance that gives a board's cards one tab stop; `Board` makes one and passes it down. */
function useBoardNavigation(options: BoardNavigationOptions = {}) {
  return usePrimitive(boardNavigation, options)
}

function BoardNavigationProvider({ handle, children }: { handle: BoardNavigationHandle; children: ReactNode }) {
  return <BoardNavigationContext value={handle}>{children}</BoardNavigationContext>
}

function BoardCardPart({ handle, id, render }: { handle: BoardNavigationHandle; id: string; render: ReactElement }) {
  return usePart(handle, "card", { value: id }, { render: render as ReactElement<Record<string, unknown>> })
}

/**
 * Makes `render`, a card's primary link or button, one of the board's cards: one tab stop for the board, and the
 * arrow keys between cards. Outside a `Board` it renders `render` unchanged.
 */
function BoardCard({ id, render }: { id: string; render: ReactElement }) {
  const handle = use(BoardNavigationContext)
  if (!handle) return render
  return <BoardCardPart handle={handle} id={id} render={render} />
}

/** A card's view of the board's tab stop, without rendering it: whether it holds the stop, and a way to take it. */
type BoardCardStop = {
  holds: () => boolean
  subscribe: (listener: () => void) => () => void
  /** Gives the card the stop without moving focus. */
  take: () => void
}

/**
 * The tab stop of the board the card `id` is in, to read in effects and event handlers: reading it never renders
 * the card, so a move renders only the two cards' primary parts. Null outside a `Board`.
 */
function useBoardCardStop(id: string): BoardCardStop | null {
  const handle = use(BoardNavigationContext)
  return useMemo(
    () =>
      handle && {
        holds: () => handle.instance.get().active === id,
        subscribe: handle.instance.subscribe,
        take: () => {
          if (handle.instance.get().active !== id) handle.api.activate(id)
        },
      },
    [handle, id],
  )
}

export { BoardCard, BoardNavigationProvider, useBoardCardStop, useBoardNavigation }
export type { BoardCardStop, BoardNavigationHandle, BoardNavigationOptions }

import {
  createChange,
  createRovingFocus,
  createTransfer,
  definePrimitive,
  idPart,
  type ChangeDetails,
  type TransferDraft,
  type TransferLists,
  type TransferReason,
} from "@ui-sdk/core"

import { transferLabels, type TransferLabels } from "@/components/ui/sortable-labels"

type BoardMove = { key: string; from: string; to: string; index: number }
type BoardTransferChangeDetails = ChangeDetails<TransferReason> & BoardMove
type BoardTransferAutoScroll = false | { edge?: number; speed?: number }

type BoardTransferOptions = {
  value?: TransferLists
  defaultValue?: TransferLists
  /** Runs once per drop or move with every list; `details` says which card went where. */
  onValueChange?: (value: TransferLists, details: BoardTransferChangeDetails) => void
  /** The lists in the order Left and Right go through them; the value's keys by default. */
  order?: readonly string[]
  /** Whether a list takes a card, like a column at its limit; lists that don't are skipped. */
  accepts?: (key: string, list: string) => boolean
  /** Cards that can't be picked up. */
  disabledKeys?: readonly string[]
  /** Cards move by their `BoardItemHandle` only, so the card's own buttons stay clickable. */
  handle?: boolean
  /**
   * `roving` (default): the handles are one tab stop with arrow keys between them. `card`: each handle is a plain
   * control of its card, for cards that are already one tab stop of the board's own (a `TaskCard`).
   */
  handleFocus?: "roving" | "card"
  /** How a drag near the board's or a column's edge scrolls it; `false` turns it off. Read on mount. */
  autoScroll?: BoardTransferAutoScroll
  itemLabel?: (key: string) => string | undefined
  listLabel?: (list: string) => string | undefined
  labels?: Partial<TransferLabels>
  /** Whether agents get `move`. A host that offers its own, confirmed action turns it off. */
  agentMoves?: boolean
}

const textOf = (el: Element | null | undefined) => el?.textContent?.replaceAll(/\s+/g, " ").trim() || undefined

function copyLists(lists: TransferLists | undefined): TransferLists {
  return Object.fromEntries(Object.entries(lists ?? {}).map(([list, keys]) => [list, [...keys]]))
}

// What the parts render, copied from the options so attributes read only state, on the server too.
function shown(options: BoardTransferOptions) {
  return {
    handle: options.handle ?? false,
    handleFocus: options.handleFocus ?? ("roving" as "roving" | "card"),
    agentMoves: options.agentMoves ?? true,
    disabledKeys: options.disabledKeys ?? ([] as readonly string[]),
    labels: { ...transferLabels, ...options.labels },
    itemLabel: options.itemLabel,
  }
}

const boardTransfer = definePrimitive({
  name: "board-transfer",
  options: {
    value: "value",
    defaultValue: "value",
    onValueChange: "callback",
    order: "list",
    accepts: "value",
    disabledKeys: "list",
    handle: "boolean",
    handleFocus: "string",
    autoScroll: "value",
    itemLabel: "value",
    listLabel: "value",
    labels: "value",
    agentMoves: "boolean",
  },
  controlled: ["value"],
  state: (options: BoardTransferOptions) => ({
    value: copyLists(options.value ?? options.defaultValue),
    moving: null as TransferDraft | null,
    focused: null as string | null,
    ...shown(options),
  }),
  sync: (options) => ({
    ...(options.value === undefined ? {} : { value: copyLists(options.value) }),
    ...shown(options),
  }),
  api: (context) => {
    const change = createChange(context)
    const labels = () => context.store.get().labels
    const disabled = (key: string) => context.store.get().disabledKeys.includes(key)
    const order = () => [...(context.options().order ?? Object.keys(context.store.get().value))]
    const elementOf = (key: string) => focus.items().find((item) => item.key === key)?.el
    const itemLabel = (key: string) => context.options().itemLabel?.(key) ?? textOf(elementOf(key)) ?? key
    const listLabel = (list: string) => context.options().listLabel?.(list) ?? list
    const autoScroll = context.options().autoScroll
    const transfer = createTransfer(context, {
      key: "value",
      draft: "moving",
      set: (value, details) => change("value", value, details),
      order,
      accepts: (key, list) => context.options().accepts?.(key, list) ?? true,
      disabled,
      label: (key) => context.options().itemLabel?.(key) ?? textOf(elementOf(key)),
      listLabel: (list) => context.options().listLabel?.(list),
      message: (message) => labels().message(message),
      createAutoScroll: autoScroll === false ? false : { edge: 48, speed: 16, ...autoScroll },
    })
    const focus = createRovingFocus(context, { slot: "card", key: "focused", orientation: () => "both" })
    const handles = createRovingFocus(context, { slot: "handle", key: "focused", orientation: () => "both" })
    const listOf = (key: string) =>
      Object.entries(context.store.get().value).find(([, keys]) => keys.includes(key))?.[0]

    return {
      transfer,
      focus,
      handles,
      labels,
      disabled,
      itemLabel,
      /** Moves a card to `index` in `list`, counting from 0, at once. */
      move(key: unknown, list: unknown, index?: unknown) {
        const lists = context.store.get().value
        const from = typeof key === "string" ? listOf(key) : undefined
        if (from === undefined) {
          const keys = Object.values(lists).flat()
          throw new RangeError(`No card "${String(key)}". Cards: ${keys.join(", ") || "none"}.`)
        }
        const id = key as string
        if (typeof list !== "string" || !(list in lists)) {
          throw new RangeError(`No list "${String(list)}". Lists: ${order().join(", ")}.`)
        }
        const size = lists[list]?.filter((each) => each !== id).length ?? 0
        const at = index === undefined ? size : index
        if (!Number.isInteger(at) || (at as number) < 0 || (at as number) > size) {
          throw new RangeError(`move takes an index from 0 to ${String(size)} in "${list}".`)
        }
        if (disabled(id)) throw new Error(`Card "${id}" can't be moved.`)
        if (list !== from && !(context.options().accepts?.(id, list) ?? true)) {
          throw new Error(`"${listLabel(list)}" doesn't take "${itemLabel(id)}".`)
        }
        return transfer.move(id, list, at as number)
      },
      keydown(event: KeyboardEvent, key: string, el: HTMLElement, roving: typeof focus) {
        if (!transfer.keydown(event, key)) roving.keydown(event, el)
      },
      cards: () =>
        order().flatMap((list) =>
          (context.store.get().value[list] ?? []).map((key) => ({
            value: key,
            label: `${itemLabel(key)} (${listLabel(list)})`,
          })),
        ),
    }
  },
  slots: (slot) => ({
    root: slot<object, { lists: TransferLists; moving: boolean }>({
      role: "group",
      state: (state, { api }) => ({ lists: api.transfer.lists(state), moving: state.moving !== null }),
      attrs: (state) => ({
        "data-moving": state.moving ? "" : undefined,
        "data-dragging": state.moving?.pointer ? "" : undefined,
        "data-handle": state.handle ? "" : undefined,
      }),
    }),
    list: slot<{ value: string }>({
      props: { value: "string" },
      role: "list",
      attrs: (state, { key }) => ({
        "data-transfer-list": idPart(key),
        "data-target": state.moving && state.moving.lists[key]?.includes(state.moving.key) ? "" : undefined,
      }),
      bind: (el, part) => part.api.transfer.bindList(el, part.key),
    }),
    card: slot<{ value: string }, { moving: boolean; dragging: boolean }>({
      props: { value: "string" },
      role: "listitem",
      state: (state, { api, key }) => ({
        moving: api.transfer.moving(state, key),
        dragging: api.transfer.dragging(state, key),
      }),
      attrs: (state, { api, key, id }) => ({
        "aria-roledescription": state.handle ? undefined : state.labels.item,
        "aria-describedby": state.handle ? undefined : `${id}-instructions`,
        "aria-disabled": state.handle || !state.disabledKeys.includes(key) ? undefined : "true",
        tabindex: state.handle ? undefined : api.focus.tabIndex(state, { key, props: { value: key } }),
        "data-transfer-item": idPart(key),
        "data-moving": api.transfer.moving(state, key) ? "" : undefined,
        "data-grabbed": api.transfer.dragging(state, key) ? "" : undefined,
        "data-disabled": state.disabledKeys.includes(key) ? "" : undefined,
      }),
      on: {
        keydown: (event, { el, api, key, store }) => {
          if (store.get().handle || !el || event.target !== el) return
          api.keydown(event, key, el, api.focus)
        },
        pointerdown: (event, { api, key, store }) => {
          if (store.get().handle || event.button !== 0) return
          api.transfer.pointerdown(event, key)
        },
      },
      bind: (el, part) => {
        const cleanups = [part.api.focus.bind(el, part), part.api.transfer.bindItem(el, part.key)]
        return () => cleanups.forEach((cleanup) => cleanup())
      },
    }),
    handle: slot<{ value: string }>({
      props: { value: { kind: "string", from: "card", required: true } },
      role: "button",
      focus: (state) => (state.handleFocus === "card" ? "native" : "roving"),
      press: { none: "Space and Enter pick the card up on keydown; a press alone does nothing." },
      attrs: (state, { api, key, id }) => {
        const moving = api.transfer.moving(state, key)
        return {
          type: "button",
          "aria-label": state.labels.handle(state.itemLabel?.(key) ?? key),
          "aria-roledescription": state.labels.item,
          "aria-describedby": `${id}-instructions`,
          "aria-pressed": String(moving),
          "aria-disabled": state.disabledKeys.includes(key) ? "true" : undefined,
          tabindex:
            state.handleFocus === "card" ? undefined : api.handles.tabIndex(state, { key, props: { value: key } }),
          "data-moving": moving ? "" : undefined,
        }
      },
      on: {
        keydown: (event, { el, api, key, store }) => {
          if (store.get().handleFocus === "card") api.transfer.keydown(event, key)
          else if (el) api.keydown(event, key, el, api.handles)
        },
        pointerdown: (event, { api, key }) => {
          if (event.button === 0) api.transfer.pointerdown(event, key)
        },
      },
      bind: (el, part) => (part.store.get().handleFocus === "card" ? undefined : part.api.handles.bind(el, part)),
    }),
    instructions: slot({
      attrs: (_state, { id }) => ({ id: `${id}-instructions`, hidden: "" }),
    }),
  }),
  agent: {
    actions: ["move"],
    items: (api) => api.cards(),
    shown: (state) => state.agentMoves,
  },
})

export { boardTransfer }
export type { BoardMove, BoardTransferAutoScroll, BoardTransferChangeDetails, BoardTransferOptions }

"use client"

import type { TransferLists } from "@ui-sdk/core"
import { createParts } from "@ui-sdk/react/primitive"
import { GripVerticalIcon } from "lucide-react"
import { createContext, use, useRef, type ComponentProps, type ReactNode, type RefObject } from "react"

import { boardTransfer, type BoardTransferOptions } from "@/components/ui/board-transfer-primitive"
import { transferLabels, type TransferLabels } from "@/components/ui/sortable-labels"
import { useFlip } from "@/components/ui/use-flip"
import { cn, cnState } from "@/lib/utils"

const Parts = createParts(boardTransfer, {
  root: "div",
  list: "div",
  card: "div",
  handle: "button",
  instructions: "div",
})

/** The lists to render, the draft's while a card moves; null when the board doesn't move cards. */
const BoardListsContext = createContext<TransferLists | null>(null)

function useBoardLists() {
  return use(BoardListsContext)
}

type BoardTransferProps = BoardTransferOptions & {
  "aria-label"?: string
  "aria-labelledby"?: string
  className?: string
  children: ReactNode
}

function BoardTransfer({ children, className, labels, ...props }: BoardTransferProps) {
  const root = useRef<HTMLDivElement>(null)
  const text = { ...transferLabels, ...labels }
  return (
    <Parts.Root
      ref={root}
      labels={labels}
      // The root transitions nothing itself; it carries the motion tokens `useFlip` reads.
      className={cn("group/board-transfer min-w-0 transition-none duration-panel ease-standard", className)}
      {...props}
    >
      {(state: { lists: TransferLists }) => (
        <>
          <FlipLists root={root} lists={state.lists} />
          <BoardListsContext value={state.lists}>{children}</BoardListsContext>
          <Parts.Instructions>{text.instructions}</Parts.Instructions>
        </>
      )}
    </Parts.Root>
  )
}

function FlipLists({ root, lists }: { root: RefObject<HTMLDivElement | null>; lists: TransferLists }) {
  useFlip(root, "[data-transfer-item]", JSON.stringify(lists))
  return null
}

function BoardList({ className, ...props }: ComponentProps<typeof Parts.List>) {
  return (
    <Parts.List
      className={cnState(
        "flex min-h-control flex-col gap-items rounded-control group-data-moving/board-transfer:data-target:bg-accent/40",
        className,
      )}
      {...props}
    />
  )
}

const cardVariantClassNames = {
  card: "flex items-start gap-inline border bg-card px-inset-item py-inset-item text-body-sm text-card-foreground shadow-surface",
  plain: "",
} as const

type BoardItemProps = ComponentProps<typeof Parts.Card> & {
  /** `card` (default) draws a card around the content; `plain` leaves it to the content, like a `TaskCard`. */
  variant?: keyof typeof cardVariantClassNames
}

/** A card that moves between the board's columns: drag it, or press Space on it (or its handle) and use the arrows. */
function BoardItem({ className, variant = "card", ...props }: BoardItemProps) {
  return (
    <Parts.Card
      className={cnState(
        cn(
          "relative min-w-0 rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring data-disabled:opacity-60 data-moving:ring-2 data-moving:ring-ring data-grabbed:opacity-40 not-group-data-handle/board-transfer:cursor-grab not-group-data-handle/board-transfer:touch-none not-group-data-handle/board-transfer:select-none",
          cardVariantClassNames[variant],
        ),
        className,
      )}
      {...props}
    />
  )
}

type BoardItemHandleProps = Omit<ComponentProps<typeof Parts.Handle>, "value"> & {
  /** The card's name; the handle is called `labels.handle(label)`. */
  label?: string
  labels?: Partial<TransferLabels>
  value?: string
}

function BoardItemHandle({ className, label, labels, children, ...props }: BoardItemHandleProps) {
  const text = { ...transferLabels, ...labels }
  return (
    <Parts.Handle
      aria-label={label === undefined ? undefined : text.handle(label)}
      className={cnState(
        "touch-target relative z-10 inline-flex size-control-sm shrink-0 cursor-grab touch-none items-center justify-center rounded-control text-muted-foreground outline-none select-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring aria-disabled:cursor-not-allowed aria-disabled:opacity-50 data-moving:bg-accent data-moving:text-accent-foreground [&_svg]:size-4",
        className,
      )}
      {...(props as ComponentProps<typeof Parts.Handle>)}
    >
      {children ?? <GripVerticalIcon />}
    </Parts.Handle>
  )
}

export { BoardItem, BoardItemHandle, BoardList, BoardTransfer, useBoardLists }
export type { BoardItemHandleProps, BoardItemProps, BoardTransferProps }
